using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Cosmos provider no longer supports indexes (they are
        // managed server-side via indexing policy). Remove HasIndex calls.
        // Was: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);

        // Breaking change 2: Discriminator property renamed from "Discriminator"
        // to "$type". Map back to old name for existing documents.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 3: Id property is now mapped to JSON "id" using
        // camelCase by default (was "Id"). For existing documents with the old
        // id format "Blog|1", we keep "id" (already camelCase), but must opt
        // out of the new simplified id-generation that no longer prepends the
        // discriminator. Restore the legacy format so reads match existing docs.
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasJsonPropertyName("id");

        // Breaking change 4: EF 9 uses simplified ids by default (just the key
        // value). Existing documents have "Blog|<key>" format. Preserve it:
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        // If already configured externally, skip.
        if (options.IsConfigured) return;
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

